{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 따릉이 결제 후 앱 오류로 이용하지 못한 경우 보상해 줄 수 있다는 규정",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제12조의3 제4항은 시장이 공공자전거 이용 중 차체 결함, 시스템 장애 및 서비스 중단 등으로 정상적인 이용이 불가능한 경우 등 불편이 발생한 경우 예산의 범위에서 공공자전거 이용권 또는 이에 상응하는 보상을 제공할 수 있다고 정하고 있다. 앱 오류로 결국 이용하지 못한 경우는 시스템 장애 등으로 정상적인 이용이 불가능한 경우에 해당할 수 있으므로, 그 요건을 충족하면 보상 제공 대상이 될 수 있다. 다만 보상은 예산의 범위에서 이용권 또는 이에 상응하는 보상으로 제공되며, 구체적인 보상 여부와 내용은 시장이 판단할 사항이다.",
          "b_ids": "자전거:제12조의3제4항, 자전거:제12조의3제4항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
